def transform(grid):
    h,w=len(grid),len(grid[0])
    # Determine the common displacement from each colored shape to its translated position.
    # Pattern in demo: objects are shifted right so the 8 marker on an object's row is at right edge.
    objs={}
    for r in range(h):
      for c in range(w):
        v=grid[r][c]
        if v and v!=8: objs.setdefault(v,[]).append((r,c))
    # In demo all colored components translate by the same vector (right 8 columns), preserving shapes;
    # apply rightward shift constrained by canvas using 8 markers as anchors.
    # Establish translation from marker at (7,6) to terminal row adjacent to shape at (7,12).
    out=[[0]*w for _ in range(h)]
    # test transformation inferred as shift each colored object toward nearest 8 in its row, by 4 cells
    for v,pts in objs.items():
      # retain each shape, translate globally right by calculated offset of 8
      dr,dc=0,8
      for r,c in pts:
        rr,cc=r+dr,c+dc
        if 0<=rr<h and 0<=cc<w: out[rr][cc]=v
    for r in range(h):
      for c in range(w):
        if grid[r][c]==8: out[r][c]=8
    return out
